examples.code:
# Illustrative, tool-agnostic pipeline definition
stages:
  - checkout
  - build:      docker build -t app:${GIT_SHA} .
  - test:       docker run --rm app:${GIT_SHA} pytest
  - scan:       trivy image --exit-code 1 --severity HIGH,CRITICAL app:${GIT_SHA}
  - tag:        docker tag app:${GIT_SHA} app:${VERSION}
  - push:       docker push app:${GIT_SHA} && docker push app:${VERSION}
  - deploy_staging:    deploy-tool apply --image app@$(docker inspect --format='{{index .RepoDigests 0}}' app:${GIT_SHA}) --env staging
  - deploy_production:  # gated on manual approval or further automated checks, using the SAME digest

